const N = Math.round(p.puffs), H = api.h, W = api.w;
const src = W * 0.5, base = H - 1;
// column of rising puffs
for (let i = 0; i < N; i++) {
  const ph = (api.t + i / N) % 1;
  const wob = api.rnd(i * 7 + 1) * 2 - 1;
  const y = base - ph * (H - 2);
  const climb = ph;
  const x = src + wob * p.drift * climb * climb + Math.sin(2 * Math.PI * (api.t + i * 0.37)) * p.drift * 0.45 * climb;
  const r = 0.7 + climb * p.girth * (0.7 + api.rnd(i * 13 + 5) * 0.6);
  const cut = p.fade;
  let a = climb < 0.12 ? climb / 0.12 : 1;
  if (climb > cut) a *= Math.max(0, 1 - (climb - cut) / (1 - cut));
  a *= p.intensity * 0.8;
  if (a <= 0.02) continue;
  // stay in the pale end of the ramp so it reads as smoke, and go paler as it thins
  const ci = climb < 0.22 ? 3 : climb < 0.5 ? 2 : climb < 0.75 ? 1 : 0;
  const cx = Math.round(x), cy = Math.round(y);
  api.blob(cx, cy, r, ci, a);
  // a soft lighter core low down gives the puff some body
  if (climb < 0.5 && r > 1.4) api.blob(cx, cy - 1, r * 0.55, ci - 1 < 0 ? 0 : ci - 1, a * 0.6);
  // break up as it climbs: loose pixels around the rim, same pale colours
  if (climb > 0.38) {
    const shred = 2 + Math.round(climb * 4);
    for (let k = 0; k < shred; k++) {
      const ang = 2 * Math.PI * (api.rnd(i * 31 + k * 3 + 2) + api.t);
      const rr = r * (0.9 + api.rnd(i * 17 + k * 5 + 3) * 1.0);
      const sx = Math.round(x + Math.cos(ang) * rr * 1.25);
      const sy = Math.round(y + Math.sin(ang) * rr * 0.7);
      api.px(sx, sy, k % 2 ? 0 : 1, a * (0.55 - climb * 0.3));
    }
  }
}
// evaporating wisps at the very top, fading out into nothing
for (let k = 0; k < 7; k++) {
  const ph2 = (api.t * 0.7 + k / 7) % 1;
  const yy = Math.round(1 + ph2 * 7);
  const xx = Math.round(src + (api.rnd(k * 11 + 9) * 2 - 1) * p.drift * 1.5 + Math.sin(2 * Math.PI * (api.t + k * 0.21)) * 1.2);
  api.px(xx, yy, 0, (1 - ph2) * 0.22 * p.intensity);
  if (ph2 < 0.5) api.px(xx + (k % 2 ? 1 : -1), yy, 0, (1 - ph2) * 0.12 * p.intensity);
}
